```sqlite
SELECT DISTINCT T2.Language FROM country AS T1 INNER JOIN countrylanguage AS T2 ON T1.Code = T2.CountryCode WHERE T1.HeadOfState = '布什' AND T2.IsOfficial = 'T';
```

```sqlite
SELECT DISTINCT T2.Language FROM country AS T1 INNER JOIN countrylanguage AS T2 ON T1.Code = T2.CountryCode WHERE T1.HeadOfState = '布什' AND T2.IsOfficial = 'T';
```

```sqlite
SELECT DISTINCT T1.Name FROM city AS T1 INNER JOIN country AS T2 ON T1.CountryCode = T2.Code WHERE T2.Continent = 'Asia' AND T1.Population > (SELECT MAX(Population) FROM city WHERE CountryCode IN (SELECT Code FROM country WHERE Continent = 'Africa'));
```

```sqlite
SELECT DISTINCT T1.Name FROM city AS T1 INNER JOIN country AS T2 ON T1.CountryCode = T2.Code WHERE T2.Continent = 'Asia' AND T1.District IN (SELECT CountryCode FROM countrylanguage WHERE Language = '中文' AND IsOfficial = 'T');
```

```sqlite
SELECT Name, IndepYear, SurfaceArea FROM country ORDER BY Population ASC LIMIT 1;
```

```sqlite
SELECT COUNT(DISTINCT c.District) FROM city c JOIN country co ON c.CountryCode = co.Code WHERE c.Population > (SELECT AVG(Population) FROM city) AND co.Region IN (SELECT Region FROM country GROUP BY Region);
```

```sqlite
SELECT AVG(CAST(JULIANDAY('now') - JULIANDAY(date_of_birth) / 365.25 AS REAL)) FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id;
```

```sqlite
